6 WITH RECURSIVE paths(startNode, endNode, path) AS (
    /*定义路径*/
    SELECT node1id AS startNode, node2id AS endNode,
    [node1id, node2id] AS path
    FROM bigquant_edge
    WHERE startNode = 1
    UNION ALL
    /*整合新的边*/
    SELECT paths.startNode AS startNode, node2id AS endNode, array_append(path, node2id) AS path
    FROM paths
    JOIN bigquant_edge ON paths.endNode = node1id
    /*防止添加重复的节点*/
    /*保证没有圆形循环发生*/
    WHERE node2id != ALL(paths.path)
)
SELECT startNode, endNode, path
FROM paths
ORDER BY length(path), path;

